"""
StructureExpert: Tiny generic priors for common web-text byte structures.

State machine over previous bytes to detect and predict:
  - URL mode
  - number/date mode
  - hex/base64 mode
  - email/domain mode
  - HTML/tag mode
  - markdown/list mode
  - quote/bracket mode
  - indent/newline rhythm mode
  - UTF-8 continuation mode
  - code-ish punctuation mode

Generic — no validation-specific strings.
Tiny code footprint — just state transitions and boost tables.
"""

from __future__ import annotations

import numpy as np


class StructureExpert:
    """
    Web-text structure priors via lightweight state machine.

    Detects structural patterns and boosts byte probabilities accordingly.
    All transitions are causal — only look at bytes_<t.
    """

    URL_MODE = "url"
    NUMBER_MODE = "number"
    HEX_MODE = "hex"
    EMAIL_MODE = "email"
    HTML_MODE = "html"
    MARKDOWN_MODE = "markdown"
    QUOTE_MODE = "quote"
    INDENT_MODE = "indent"
    UTF8_CONT_MODE = "utf8_cont"
    CODE_MODE = "code"
    NORMAL_MODE = "normal"

    def __init__(self):
        self._mode = self.NORMAL_MODE
        self._mode_state: dict = {}
        self._prev_byte: int | None = None
        self._consecutive_newlines = 0
        self._consecutive_spaces = 0

    def predict_byte(self, ctx: np.ndarray, next_byte: int) -> float:
        dist = self.predict_distribution(ctx)
        return float(dist[next_byte]) if next_byte < len(dist) else 0.0

    def predict_distribution(self, ctx: np.ndarray) -> np.ndarray:
        """Return probability distribution over 256 bytes with structure boost."""
        base_probs = np.ones(256, dtype=np.float32) / 256.0

        mode = self._detect_mode(ctx)

        if mode == self.NORMAL_MODE:
            return base_probs

        boost = self._mode_boost_table(mode)
        total = boost.sum()
        if total > 0:
            boost /= total
        else:
            boost = base_probs

        confidence = min(self._mode_confidence(mode), 1.0)
        probs = base_probs * (1 - confidence) + boost * confidence
        probs /= probs.sum()

        return probs

    def _detect_mode(self, ctx: np.ndarray) -> str:
        """Detect current structural mode from context."""
        if len(ctx) == 0:
            return self.NORMAL_MODE

        last_bytes = list(ctx[-8:]) if len(ctx) >= 8 else list(ctx)

        if self._detect_url(last_bytes):
            return self.URL_MODE
        if self._detect_html_tag(last_bytes):
            return self.HTML_MODE
        if self._detect_number_or_date(last_bytes):
            return self.NUMBER_MODE
        if self._detect_hex(last_bytes):
            return self.HEX_MODE
        if self._detect_email(last_bytes):
            return self.EMAIL_MODE
        if self._detect_markdown(last_bytes):
            return self.MARKDOWN_MODE
        if self._detect_code(last_bytes):
            return self.CODE_MODE

        if self._consecutive_newlines > 2:
            return self.INDENT_MODE
        if self._prev_byte is not None and (self._prev_byte & 0xC0) == 0x80:
            return self.UTF8_CONT_MODE

        return self.NORMAL_MODE

    def _detect_url(self, last_bytes: list[int]) -> bool:
        if len(last_bytes) < 4:
            return False
        s = bytes(last_bytes[-6:])
        return (
            b"http" in s or b"www." in s or b".com" in s or b"://" in s or
            b"github" in s or b".org" in s or b".io" in s
        )

    def _detect_html_tag(self, last_bytes: list[int]) -> bool:
        if not last_bytes:
            return False
        if last_bytes[-1] == ord(">"):
            return True
        if len(last_bytes) >= 2 and last_bytes[-2] == ord("<"):
            return True
        if len(last_bytes) >= 3 and last_bytes[-1] == ord("/") and last_bytes[-3] == ord("<"):
            return True
        return False

    def _detect_number_or_date(self, last_bytes: list[int]) -> bool:
        if not last_bytes:
            return False
        n = last_bytes[-1]
        if ord("0") <= n <= ord("9"):
            return True
        if n in (ord("-"), ord("/"), ord(":"), ord("."), ord(",")):
            count = sum(1 for b in last_bytes if ord("0") <= b <= ord("9"))
            return count >= 2
        return False

    def _detect_hex(self, last_bytes: list[int]) -> bool:
        if len(last_bytes) < 2:
            return False
        s = bytes(last_bytes[-4:])
        return (b"0x" in s.lower() or
                all(c in b"0123456789abcdefABCDEF" for c in s))

    def _detect_email(self, last_bytes: list[int]) -> bool:
        if len(last_bytes) < 3:
            return False
        s = bytes(last_bytes[-6:])
        return b"@" in s or b".com" in s or b".org" in s

    def _detect_markdown(self, last_bytes: list[int]) -> bool:
        if not last_bytes:
            return False
        n = last_bytes[-1]
        if n in (ord("#"), ord("*"), ord("-"), ord(">"), ord("!")):
            return True
        if len(last_bytes) >= 2 and last_bytes[-1] == ord(" ") and last_bytes[-2] in (ord("#"), ord("-"), ord("*")):
            return True
        return False

    def _detect_code(self, last_bytes: list[int]) -> bool:
        if len(last_bytes) < 2:
            return False
        code_chars = set(b"{}[]();:=+-*/<>|&^%$#@!~`|\\\"'_")
        count = sum(1 for b in last_bytes if b in code_chars)
        return count >= 2

    def _mode_boost_table(self, mode: str) -> np.ndarray:
        boost = np.ones(256, dtype=np.float32)

        if mode == self.URL_MODE:
            url_chars = set(list(range(ord("0"), ord("9") + 1)) +
                           list(range(ord("a"), ord("z") + 1)) +
                           list(range(ord("A"), ord("Z") + 1)) +
                           [ord("-"), ord("_"), ord("."), ord("/"), ord(":"), ord("?"), ord("&"), ord("=")])
            for c in url_chars:
                boost[c] *= 5.0

        elif mode == self.NUMBER_MODE:
            for c in range(ord("0"), ord("9") + 1):
                boost[c] *= 4.0
            for c in [ord("-"), ord("/"), ord(":"), ord("."), ord(","), ord("%"), ord("$")]:
                boost[c] *= 2.0

        elif mode == self.HEX_MODE:
            for c in range(ord("0"), ord("9") + 1):
                boost[c] *= 3.0
            for c in range(ord("a"), ord("f") + 1):
                boost[c] *= 3.0
            for c in range(ord("A"), ord("F") + 1):
                boost[c] *= 3.0
            boost[ord("x")] *= 2.0

        elif mode == self.HTML_MODE:
            tag_chars = set(list(range(ord("a"), ord("z") + 1)) +
                          list(range(ord("A"), ord("Z") + 1)) +
                          [ord("/"), ord("="), ord('"'), ord("'"), ord(">"), ord("<"), ord("!"), ord("-")])
            for c in tag_chars:
                boost[c] *= 4.0

        elif mode == self.UTF8_CONT_MODE:
            for c in range(0x80, 0xC0):
                boost[c] *= 10.0

        elif mode == self.CODE_MODE:
            code_chars = set(b"{}[]();:=+-*/<>|&^%$#@!~`|\\\"'_.,")
            for c in code_chars:
                boost[c] *= 3.0
            for c in range(ord("0"), ord("9") + 1):
                boost[c] *= 2.0

        return boost

    def _mode_confidence(self, mode: str) -> float:
        if mode == self.NORMAL_MODE:
            return 0.0
        if mode in (self.UTF8_CONT_MODE,):
            return 0.9
        return 0.3

    def update(self, ctx: np.ndarray, byte_val: int) -> None:
        """
        Update state AFTER scoring (causal requirement).
        """
        self._prev_byte = byte_val

        if byte_val == ord("\n"):
            self._consecutive_newlines += 1
        else:
            self._consecutive_newlines = 0

        if byte_val == ord(" "):
            self._consecutive_spaces += 1
        else:
            self._consecutive_spaces = 0

    def reset(self) -> None:
        self._mode = self.NORMAL_MODE
        self._mode_state.clear()
        self._prev_byte = None
        self._consecutive_newlines = 0
        self._consecutive_spaces = 0

"""
GrammarTemplateExpert: Online document-local template induction.

THE CORE NOVELTY CONTRIBUTION.

Discovers repeated byte span templates within a document and
predicts bytes through active templates.

Target patterns:
  "Posted by {NAME} on {DATE}"
  "<a href=\"{URL}\">{TITLE}</a>"
  "Copyright © {YEAR} {SITE}"
  "Step {N}: {TEXT}"

Implementation:
  1. Detect repeated byte spans via rolling hash
  2. Align similar spans to infer literal segments + variable slots
  3. Activate templates when prefix matches literal segments
  4. Generate normalized byte predictions for next literal or slot type

Causal: template created only from past bytes.
"""

from __future__ import annotations

import hashlib
import numpy as np
from typing import Optional


SlotType = str  # "number" | "url" | "domain" | "name" | "word" | "quoted" | "unknown"


class Template:
    __slots__ = (
        "literal_prefixes", "slot_types", "literal_suffixes",
        "support_count", "last_seen_position", "confidence",
        "active_state", "hash", "span_len",
    )

    def __init__(self):
        self.literal_prefixes: list[bytes] = []
        self.slot_types: list[SlotType] = []
        self.literal_suffixes: list[bytes] = []
        self.support_count: int = 0
        self.last_seen_position: int = 0
        self.confidence: float = 0.0
        self.active_state: int = 0  # 0=idle, 1=in_prefix, 2=in_slot, 3=complete
        self.hash: int = 0
        self.span_len: int = 0


class GrammarTemplateExpert:
    """
    Online grammar/template induction for document-local repeated structures.

    This is the BREAKTHROUGH candidate. If it delivers >=0.05 BPB independent
    gain, it justifies the entire RECAP approach.

    Kill criteria: if gain < 0.05 BPB over PPM+LZ+phrase, it gets cut.
    """

    def __init__(
        self,
        max_templates: int = 16,
        min_template_len: int = 16,
        max_span_len: int = 256,
        history_size: int = 8192,
        min_support: int = 2,
    ):
        self.max_templates = max_templates
        self.min_template_len = min_template_len
        self.max_span_len = max_span_len
        self.history_size = history_size
        self.min_support = min_support

        self._history: list[int] = []
        self._templates: list[Template] = []
        self._active_template: Template | None = None
        self._position_in_template: int = 0

        self._span_hashes: dict[int, list[tuple[int, int]]] = {}
        self._slot_classifier = SlotClassifier()

    def predict_byte(self, ctx: np.ndarray, next_byte: int) -> float:
        dist = self.predict_distribution(ctx)
        return float(dist[next_byte]) if next_byte < len(dist) else 0.0

    def predict_distribution(self, ctx: np.ndarray) -> np.ndarray:
        """Return probability distribution boosted by active template."""
        probs = np.ones(256, dtype=np.float32) / 256.0

        if self._active_template is None:
            return probs

        template = self._active_template
        state = template.active_state

        if state == 1:
            prefix_idx = self._position_in_template
            if prefix_idx < len(template.literal_prefixes):
                literal = template.literal_prefixes[prefix_idx]
                boost = self._literal_boost(literal, probs)
                return boost

        elif state == 2:
            slot_idx = self._position_in_template - len(template.literal_prefixes)
            if slot_idx < len(template.slot_types):
                slot_type = template.slot_types[slot_idx]
                boost = self._slot_boost(slot_type, probs)
                return boost

        return probs

    def _literal_boost(self, literal: bytes, base: np.ndarray) -> np.ndarray:
        """Boost bytes matching expected literal sequence."""
        probs = base.copy()
        for i, expected_byte in enumerate(literal):
            if 0 <= expected_byte < 256:
                probs[expected_byte] *= 3.0

        total = probs.sum()
        if total > 0:
            probs /= total
        return probs

    def _slot_boost(self, slot_type: SlotType, base: np.ndarray) -> np.ndarray:
        """Boost bytes consistent with slot type."""
        probs = base.copy()

        if slot_type == "number":
            for c in range(ord("0"), ord("9") + 1):
                probs[c] *= 5.0
            for c in [ord("-"), ord("."), ord(","), ord("/")]:
                probs[c] *= 2.0

        elif slot_type == "url":
            url_chars = set(range(ord("0"), ord("9") + 1))
            url_chars.update(range(ord("a"), ord("z") + 1))
            url_chars.update(range(ord("A"), ord("Z") + 1))
            url_chars.update([ord("-"), ord("_"), ord("."), ord("/"), ord(":"), ord("?"), ord("&"), ord("="), ord("%"), ord("#")])
            for c in url_chars:
                probs[c] *= 4.0

        elif slot_type == "domain":
            domain_chars = set(range(ord("0"), ord("9") + 1))
            domain_chars.update(range(ord("a"), ord("z") + 1))
            domain_chars.update([ord("-"), ord(".")])
            for c in domain_chars:
                probs[c] *= 3.0

        elif slot_type == "word":
            for c in range(ord("a"), ord("z") + 1):
                probs[c] *= 3.0
            for c in range(ord("A"), ord("Z") + 1):
                probs[c] *= 2.0
            probs[ord(" ")] *= 2.0
            probs[ord("-")] *= 2.0

        elif slot_type == "quoted":
            for c in range(32, 127):
                probs[c] *= 2.0

        total = probs.sum()
        if total > 0:
            probs /= total
        return probs

    def update(self, ctx: np.ndarray, byte_val: int) -> None:
        """
        Update template state AFTER scoring (causal requirement).

        Also discovers new template candidates from repeated spans.
        """
        self._history.append(byte_val)
        if len(self._history) > self.history_size:
            self._history = self._history[-self.history_size:]

        self._detect_template_candidates()

        if self._active_template:
            self._advance_template_state(byte_val)

    def _detect_template_candidates(self) -> None:
        """Find repeated spans and attempt template induction."""
        n = len(self._history)
        if n < self.min_template_len * 2:
            return

        for span_len in range(self.min_template_len, min(self.max_span_len, n // 2)):
            if n < span_len * 2:
                continue

            current_span = bytes(self._history[n - span_len:])
            h = hashlib.md5(current_span).digest()[0:4]
            h_int = int.from_bytes(h, "big") & 0x7FFFFFFF

            if h_int not in self._span_hashes:
                self._span_hashes[h_int] = []
            self._span_hashes[h_int].append((n - span_len, n))

            positions = self._span_hashes[h_int]
            if len(positions) >= self.min_support:
                if not self._template_exists(h_int):
                    tmpl = self._induce_template(positions, span_len)
                    if tmpl:
                        self._templates.append(tmpl)
                        if len(self._templates) > self.max_templates:
                            self._templates.sort(key=lambda t: t.confidence * t.support_count)
                            self._templates = self._templates[: self.max_templates]

    def _template_exists(self, h: int) -> bool:
        return any(t.hash == h for t in self._templates)

    def _induce_template(self, positions: list[tuple[int, int]], span_len: int) -> Template | None:
        """Induce template from aligned repeated spans."""
        if len(positions) < self.min_support:
            return None

        spans = []
        for start, end in positions:
            span = bytes(self._history[start:end])
            spans.append(span)

        aligned = self._align_spans(spans)
        if aligned is None:
            return None

        prefixes, slot_types, suffixes = aligned

        template = Template()
        template.hash = hashlib.md5(bytes(self._history[positions[0][0]:positions[0][1]])).digest()[0:4]
        template.hash = int.from_bytes(template.hash, "big") & 0x7FFFFFFF
        template.literal_prefixes = [p for p in prefixes if p]
        template.slot_types = slot_types
        template.literal_suffixes = [s for s in suffixes if s]
        template.support_count = len(positions)
        template.confidence = min(len(positions) / 5.0, 1.0)
        template.span_len = span_len
        template.last_seen_position = positions[-1][0]

        return template

    def _align_spans(self, spans: list[bytes]) -> tuple[list[bytes], list[SlotType], list[bytes]] | None:
        """Align multiple spans to find literal vs variable patterns."""
        if len(spans) < 2:
            return None

        min_len = min(len(s) for s in spans)
        max_len = max(len(s) for s in spans)

        if max_len - min_len > 32:
            return None

        avg_len = int(np.mean([len(s) for s in spans]))

        prefixes: list[bytes] = []
        slot_types: list[SlotType] = []
        suffixes: list[bytes] = []

        for pos in range(min(64, avg_len)):
            bytes_at_pos = [s[pos] for s in spans if pos < len(s)]
            if not bytes_at_pos:
                continue

            if len(set(bytes_at_pos)) == 1:
                prefixes.append(bytes([bytes_at_pos[0]]))
            else:
                slot_type = self._slot_classifier.classify(bytes_at_pos)
                if slot_type:
                    slot_types.append(slot_type)
                else:
                    return None

        for pos in range(-1, -min(8, min_len), -1):
            bytes_at_pos = [s[pos] for s in spans if abs(pos) <= len(s)]
            if not bytes_at_pos:
                continue
            if len(set(bytes_at_pos)) == 1:
                suffixes.insert(0, bytes([bytes_at_pos[0]]))
            else:
                break

        return prefixes, slot_types, suffixes

    def _advance_template_state(self, byte_val: int) -> None:
        """Advance state machine for active template."""
        if self._active_template is None:
            return

        template = self._active_template
        state = template.active_state

        if state == 0:
            prefix_idx = 0
            if prefix_idx < len(template.literal_prefixes):
                expected = template.literal_prefixes[prefix_idx]
                if len(expected) > 0 and byte_val == expected[0]:
                    template.active_state = 1
                    self._position_in_template = 0

        elif state == 1:
            prefix_idx = self._position_in_template
            if prefix_idx < len(template.literal_prefixes):
                expected = template.literal_prefixes[prefix_idx]
                if byte_val == expected[self._position_in_template]:
                    self._position_in_template += 1
                    if self._position_in_template >= len(expected):
                        template.active_state = 2
                        self._position_in_template = len(template.literal_prefixes)

        elif state == 2:
            slot_idx = self._position_in_template - len(template.literal_prefixes)
            if slot_idx < len(template.slot_types):
                slot_type = template.slot_types[slot_idx]
                if not self._slot_classifier.matches(slot_type, byte_val):
                    self._deactivate_template()
                    return

                if self._slot_classifier.is_complete(slot_type, byte_val):
                    self._position_in_template += 1
                    if self._position_in_template >= len(template.literal_prefixes) + len(template.slot_types):
                        template.active_state = 3
                        template.confidence = min(template.confidence * 1.1, 1.0)

    def _deactivate_template(self) -> None:
        """Deactivate current template."""
        if self._active_template:
            self._active_template.active_state = 0
            self._active_template = None
        self._position_in_template = 0

    def activate_template(self, template: Template) -> None:
        """Manually activate a template (for when prefix matches)."""
        template.active_state = 0
        template.confidence = min(template.confidence * 1.2, 1.0)
        self._active_template = template
        self._position_in_template = 0

    def features(self) -> dict:
        """Return gate features."""
        if self._active_template:
            return {
                "grammar_template_confidence": self._active_template.confidence,
                "grammar_slot_type": self._active_template.slot_types[
                    max(0, self._position_in_template - len(self._active_template.literal_prefixes))
                ] if self._active_template.slot_types else "none",
            }
        return {
            "grammar_template_confidence": 0.0,
            "grammar_slot_type": "none",
        }

    def reset(self) -> None:
        self._history.clear()
        self._templates.clear()
        self._active_template = None
        self._position_in_template = 0
        self._span_hashes.clear()


class SlotClassifier:
    """Classifies byte sequences into slot types."""

    SLOT_PATTERNS = {
        "number": (
            lambda b: ord("0") <= b <= ord("9"),
            lambda b: b in (ord("-"), ord("."), ord(","), ord("/")),
            lambda b: b == ord("."),
        ),
        "url": (
            lambda b: ord("0") <= b <= ord("9") or ord("a") <= b <= ord("z") or ord("A") <= b <= ord("Z") or b in (ord("-"), ord("_"), ord("."), ord("/"), ord(":"), ord("?"), ord("&"), ord("="), ord("%"), ord("#")),
            lambda b: False,
            lambda b: False,
        ),
        "domain": (
            lambda b: ord("0") <= b <= ord("9") or ord("a") <= b <= ord("z") or ord("A") <= b <= ord("Z") or b in (ord("-"), ord(".")),
            lambda b: False,
            lambda b: False,
        ),
        "name": (
            lambda b: ord("a") <= b <= ord("z") or ord("A") <= b <= ord("Z") or b in (ord(" "), ord("-"), ord("'"), ord(".")),
            lambda b: False,
            lambda b: False,
        ),
        "word": (
            lambda b: ord("a") <= b <= ord("z") or ord("A") <= b <= ord("Z"),
            lambda b: ord("0") <= b <= ord("9") or b == ord("'"),
            lambda b: b == ord(" ") or b == ord("-"),
        ),
    }

    def classify(self, bytes_at_pos: list[int]) -> SlotType | None:
        for slot_type, (first_char, mid_char, last_char) in self.SLOT_PATTERNS.items():
            if all(first_char(b) for b in bytes_at_pos):
                return slot_type
        return None

    def matches(self, slot_type: SlotType, byte_val: int) -> bool:
        if slot_type not in self.SLOT_PATTERNS:
            return True
        first_char, _, _ = self.SLOT_PATTERNS[slot_type]
        return bool(first_char(byte_val))

    def is_complete(self, slot_type: SlotType, byte_val: int) -> bool:
        if slot_type not in self.SLOT_PATTERNS:
            return False
        _, _, last_char = self.SLOT_PATTERNS[slot_type]
        return bool(last_char(byte_val))

"""
MixtureMixer: Combines expert outputs into final probability distribution.

Supports:
  - Fixed/rule-based mixture (for baseline)
  - Learned gate mixture
  - Per-expert BPB tracking
"""

from __future__ import annotations

import numpy as np
from typing import Optional

from recap.gate import LearnedGate


class MixtureMixer:
    """
    Final probability distribution from expert mixture.

    Modes:
      - FIXED: hard-coded expert weights (for baseline)
      - LEARNED: uses LearnedGate MLP
      - RULES: confidence-based routing
    """

    MODE_FIXED = "fixed"
    MODE_LEARNED = "learned"
    MODE_RULES = "rules"

    def __init__(
        self,
        mode: str = MODE_FIXED,
        device: str = "cuda",
    ):
        self.mode = mode
        self.device = device

        self._gate = LearnedGate(device) if mode == MODE_LEARNED else None

        self._expert_names = [
            "neural", "ppm", "lz", "phrase", "structure", "grammar", "residual"
        ]

        self._fixed_weights = {
            "neural": 0.5,
            "ppm": 0.2,
            "lz": 0.15,
            "phrase": 0.05,
            "structure": 0.05,
            "grammar": 0.03,
            "residual": 0.02,
        }

        self._expert_probs: dict[str, np.ndarray] = {}
        self._expert_losses: dict[str, list[float]] = {}
        self._expert_usage: dict[str, list[float]] = {}

        for name in self._expert_names:
            self._expert_losses[name] = []
            self._expert_usage[name] = []

    def set_expert_prob(self, name: str, probs: np.ndarray) -> None:
        """Set byte probability distribution from an expert."""
        self._expert_probs[name] = probs.astype(np.float32)

    def predict(self, features: dict) -> np.ndarray:
        """
        Get final byte probability distribution.

        Returns:
            final_probs[256] normalized
        """
        if not self._expert_probs:
            return np.ones(256, dtype=np.float32) / 256.0

        if self.mode == self.MODE_FIXED:
            return self._fixed_mixture()

        elif self.mode == self.MODE_LEARNED:
            return self._learned_mixture(features)

        elif self.mode == self.MODE_RULES:
            return self._rules_mixture(features)

        return self._fixed_mixture()

    def _fixed_mixture(self) -> np.ndarray:
        """Fixed weight mixture."""
        final = np.zeros(256, dtype=np.float32)

        for name, weight in self._fixed_weights.items():
            if name in self._expert_probs:
                final += weight * self._expert_probs[name]

        total = final.sum()
        if total > 0:
            final /= total
        else:
            final[:] = 1.0 / 256.0

        return final

    def _learned_mixture(self, features: dict) -> np.ndarray:
        """Learned gate mixture."""
        if self._gate is None:
            return self._fixed_mixture()

        weights = self._gate.forward(features)

        final = np.zeros(256, dtype=np.float32)
        for i, name in enumerate(self._expert_names):
            if name in self._expert_probs:
                final += weights[i] * self._expert_probs[name]

        total = final.sum()
        if total > 0:
            final /= total
        else:
            final[:] = 1.0 / 256.0

        for i, name in enumerate(self._expert_names):
            self._expert_usage[name].append(float(weights[i]))

        return final

    def _rules_mixture(self, features: dict) -> np.ndarray:
        """Rule-based confidence routing."""
        final = np.zeros(256, dtype=np.float32)
        total_weight = 0.0

        neural_ent = features.get("neural_entropy", 8.0)
        ppm_ent = features.get("ppm_entropy", 5.0)
        lz_match = features.get("lz_longest_match", 0)
        grammar_conf = features.get("grammar_template_confidence", 0.0)

        if "neural" in self._expert_probs:
            neural_weight = max(0.1, 1.0 - neural_ent / 10.0)
            final += neural_weight * self._expert_probs["neural"]
            total_weight += neural_weight

        if "ppm" in self._expert_probs:
            ppm_weight = max(0.05, 0.3 - ppm_ent / 20.0)
            final += ppm_weight * self._expert_probs["ppm"]
            total_weight += ppm_weight

        if lz_match > 8 and "lz" in self._expert_probs:
            lz_weight = min(0.4, lz_match / 128.0)
            final += lz_weight * self._expert_probs["lz"]
            total_weight += lz_weight

        if grammar_conf > 0.3 and "grammar" in self._expert_probs:
            final += grammar_conf * self._expert_probs["grammar"]
            total_weight += grammar_conf

        for name in ["phrase", "structure"]:
            if name in self._expert_probs:
                final += 0.05 * self._expert_probs[name]
                total_weight += 0.05

        if total_weight > 0:
            final /= total_weight
        else:
            final[:] = 1.0 / 256.0

        return final

    def record_loss(self, name: str, loss: float) -> None:
        """Record per-expert loss for metrics."""
        if name in self._expert_losses:
            self._expert_losses[name].append(loss)

    def get_metrics(self) -> dict:
        """Return per-expert metrics."""
        metrics = {}

        for name in self._expert_names:
            losses = self._expert_losses.get(name, [])
            usage = self._expert_usage.get(name, [])

            if losses:
                avg_loss = np.mean(losses)
                avg_bpb = (avg_loss / np.log(2)) * 0.75
                metrics[f"{name}_avg_loss"] = float(avg_loss)
                metrics[f"{name}_avg_bpb"] = float(avg_bpb)
            else:
                metrics[f"{name}_avg_loss"] = None
                metrics[f"{name}_avg_bpb"] = None

            if usage:
                metrics[f"{name}_avg_weight"] = float(np.mean(usage))
            else:
                metrics[f"{name}_avg_weight"] = None

        return metrics

    def reset_metrics(self) -> None:
        """Clear all recorded metrics."""
        for name in self._expert_names:
            self._expert_losses[name].clear()
            self._expert_usage[name].clear()

    def predict_byte(self, features: dict, byte_val: int) -> float:
        """Convenience: predict probability of specific byte."""
        dist = self.predict(features)
        return float(dist[byte_val]) if byte_val < len(dist) else 0.0

"""
Metrics: Per-expert BPB tracking and reporting.

Tracks during evaluation:
  - per-expert BPBs
  - expert usage weights
  - normalization failures
  - worst surprise spans
  - byte class BPBs
  - mode-specific BPBs
"""

from __future__ import annotations

import math
import numpy as np
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class ExpertMetrics:
    """Metrics for a single expert."""
    name: str

    n_tokens: int = 0
    loss_sum: float = 0.0
    entropy_sum: float = 0.0

    n_zero_prob: int = 0
    n_infinite_loss: int = 0

    top_probs: list[float] = field(default_factory=list)
    entropies: list[float] = field(default_factory=list)

    def add_token(self, prob: float, entropy: float):
        self.n_tokens += 1
        if prob > 0:
            self.loss_sum += -math.log(prob)
        else:
            self.loss_sum += 25.0
            self.n_zero_prob += 1
        self.entropy_sum += entropy
        self.top_probs.append(prob)
        self.entropies.append(entropy)

    @property
    def avg_loss(self) -> float:
        return self.loss_sum / max(self.n_tokens, 1)

    @property
    def avg_entropy(self) -> float:
        return self.entropy_sum / max(self.n_tokens, 1)

    @property
    def bpb(self) -> float:
        avg_loss = self.avg_loss
        bits_per_token = avg_loss / math.log(2)
        tokens_per_byte = 0.75
        return bits_per_token * tokens_per_byte

    @property
    def zero_prob_pct(self) -> float:
        return self.n_zero_prob / max(self.n_tokens, 1)


class MetricsCollector:
    """
    Collects comprehensive metrics during RECAP evaluation.

    Tracks:
      - Per-expert BPBs
      - Per-expert usage distribution
      - Normalization failures
      - Worst surprise spans
      - Byte class BPBs
      - Mode-specific BPBs
    """

    EXPERT_NAMES = [
        "neural", "ppm", "lz", "phrase", "structure", "grammar", "residual"
    ]

    BYTE_CLASSES = {
        "ascii_letter": range(ord("a"), ord("z") + 1) + range(ord("A"), ord("Z") + 1),
        "digit": range(ord("0"), ord("9") + 1),
        "whitespace": [ord(" "), ord("\n"), ord("\t"), ord("\r")],
        "punctuation": range(ord("!"), ord("/") + 1),
        "symbol": range(ord(":"), ord("@") + 1),
        "high_byte": range(0x80, 0xC0),
        "control": range(0x00, 0x20),
    }

    def __init__(self):
        self._experts: dict[str, ExpertMetrics] = {
            name: ExpertMetrics(name) for name in self.EXPERT_NAMES
        }
        self._final_mixture = ExpertMetrics("final")

        self._byte_classes: dict[str, ExpertMetrics] = {
            name: ExpertMetrics(name) for name in self.BYTE_CLASSES.keys()
        }

        self._normalization_failures: int = 0
        self._total_tokens: int = 0

        self._worst_surprises: list[tuple[float, int]] = []
        self._max_worst = 100

    def record_expert(self, name: str, prob: float, entropy: float) -> None:
        """Record a token prediction from an expert."""
        if name in self._experts:
            self._experts[name].add_token(prob, entropy)

    def record_final(self, prob: float, entropy: float) -> None:
        """Record final mixture prediction."""
        self._final_mixture.add_token(prob, entropy)

    def record_byte_class(self, byte_val: int, prob: float, entropy: float) -> None:
        """Record prediction broken down by byte class."""
        for class_name, byte_range in self.BYTE_CLASSES.items():
            if byte_val in byte_range:
                if class_name in self._byte_classes:
                    self._byte_classes[class_name].add_token(prob, entropy)
                break

    def record_normalization_failure(self) -> None:
        """Increment normalization failure counter."""
        self._normalization_failures += 1

    def record_surprise(self, surprise: float, byte_val: int) -> None:
        """Record a high-surprise event."""
        if len(self._worst_surprises) < self._max_worst:
            self._worst_surprises.append((surprise, byte_val))
            self._worst_surprises.sort(reverse=True)
            self._worst_surprises = self._worst_surprises[: self._max_worst]
        else:
            min_surprise = min(s for s, _ in self._worst_surprises)
            if surprise > min_surprise:
                self._worst_surprises.append((surprise, byte_val))
                self._worst_surprises.sort(reverse=True)
                self._worst_surprises = self._worst_surprises[: self._max_worst]

    def summary(self) -> dict:
        """Return comprehensive metrics summary."""
        result = {
            "total_tokens": self._total_tokens,
            "normalization_failures": self._normalization_failures,
            "normalization_failure_rate": (
                self._normalization_failures / max(self._total_tokens, 1)
            ),
        }

        for name, m in self._experts.items():
            result[f"expert_{name}_bpb"] = m.bpb
            result[f"expert_{name}_avg_loss"] = m.avg_loss
            result[f"expert_{name}_avg_entropy"] = m.avg_entropy
            result[f"expert_{name}_zero_prob_pct"] = m.zero_prob_pct

        for name, m in self._byte_classes.items():
            if m.n_tokens > 0:
                result[f"byte_class_{name}_bpb"] = m.bpb
                result[f"byte_class_{name}_n_tokens"] = m.n_tokens

        result["final_bpb"] = self._final_mixture.bpb
        result["final_avg_loss"] = self._final_mixture.avg_loss

        if self._worst_surprises:
            result["worst_surprises"] = [
                {"surprise": s, "byte": b} for s, b in self._worst_surprises[:10]
            ]

        return result

    def reset(self) -> None:
        """Clear all metrics."""
        self._experts = {
            name: ExpertMetrics(name) for name in self.EXPERT_NAMES
        }
        self._final_mixture = ExpertMetrics("final")
        self._byte_classes = {
            name: ExpertMetrics(name) for name in self.BYTE_CLASSES.keys()
        }
        self._normalization_failures = 0
        self._total_tokens = 0
        self._worst_surprises.clear()

